#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("kandydaci.txt");
    string imie;
    int pisemny, ustny;
    vector<pair<double, string>> ranking;
    while (plik >> imie >> pisemny >> ustny) {
        double sr = 0.6 * pisemny + 0.4 * ustny;
        ranking.push_back({sr, imie});
    }
    sort(ranking.begin(), ranking.end(), [](auto& a, auto& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    cout << fixed << setprecision(2);
    cout << "Ranking kandydatow:" << endl;
    for (int i = 0; i < (int)ranking.size(); i++) {
        if (i + 1 < 10) cout << " ";
        cout << i + 1 << ". " << ranking[i].second << ": " << ranking[i].first << endl;
    }
    cout << "Top 3:" << endl;
    double sumaTop = 0;
    for (int i = 0; i < 3; i++) {
        cout << "   " << ranking[i].second << " (" << ranking[i].first << ")" << endl;
        sumaTop += ranking[i].first;
    }
    cout << "Srednia top 3: " << sumaTop / 3 << endl;
    return 0;
}
